//! The production source of the former `server/mod.rs`, for source-text guards.
//!
//! Generated by the split that turned `server/mod.rs` into responsibility
//! submodules: every non-test file it produced is listed here, so a guard that
//! used to `include_str!("mod.rs")` reads the same code through
//! [`server_source`] (all of it) or [`router_source`] (the route table).

/// Pairs each path (relative to `server/`) with that file's contents.
macro_rules! server_sources {
    ($($path:literal,)*) => {
        &[$(($path, include_str!(concat!("../", $path)))),*]
    };
}

