/// All production source of the former `server/mod.rs`, LF-normalized.
pub(crate) fn server_source() -> String {
    joined(SERVER_SOURCES.iter().map(|(_, text)| *text))
}

/// The route table: `create_router` and the route builders it merges.
pub(crate) fn router_source() -> String {
    joined(
        SERVER_SOURCES
            .iter()
            .filter(|(path, _)| path.starts_with("http_router/"))
            .map(|(_, text)| *text),
    )
}

/// LF-normalized, with the `pub(in crate::server)` the split added to formerly
/// private items removed again, so a guard that anchors on `\nasync fn name(`
/// or on an item's first line reads the spelling it was written against.
fn joined<'a>(texts: impl Iterator<Item = &'a str>) -> String {
    texts
        .map(|text| {
            text.replace("\r\n", "\n")
                .replace("pub(in crate::server) ", "")
        })
        .collect::<Vec<_>>()
        .join("\n")
}
